# apply-db-lock-fix.ps1 -- ONE-SHOT: writes the fixed app\__init__.py
# (PRAGMA busy_timeout fix) AND the known-good make-msi.bat (absolute
# nssm.exe path fix + self-healing nssm fetch), overwriting whatever
# is currently there, then rebuilds automatically. This removes any
# chance of an old cached make-msi.bat being used by accident.
#
# Run from the project ROOT (same folder as main.py, app\).

$ErrorActionPreference = "Stop"
Set-Location -Path $PSScriptRoot

if (-not (Test-Path "main.py")) {
    Write-Host "ERROR: main.py not found in this folder." -ForegroundColor Red
    Write-Host "Run this from the project root."
    Read-Host "Press Enter to close"
    exit 1
}
if (-not (Test-Path "app")) {
    Write-Host "ERROR: app\ folder not found in this location." -ForegroundColor Red
    Read-Host "Press Enter to close"
    exit 1
}

Write-Host "Backing up existing app\__init__.py..."
Copy-Item "app\__init__.py" "app\__init__.py.bak" -Force
if (Test-Path "make-msi.bat") {
    Write-Host "Backing up existing make-msi.bat..."
    Copy-Item "make-msi.bat" "make-msi.bat.bak" -Force
}

$initB64 = ''
$makeMsiB64 = ''

Write-Host "Writing app\__init__.py ..."
try {
    [IO.File]::WriteAllBytes((Join-Path $PSScriptRoot "app\__init__.py"), [Convert]::FromBase64String($initB64))
} catch {
    Write-Host "ERROR: failed to write app\__init__.py -- $_" -ForegroundColor Red
    Read-Host "Press Enter to close"
    exit 1
}

Write-Host "Writing make-msi.bat (known-good version, overwriting any old copy) ..."
try {
    [IO.File]::WriteAllBytes((Join-Path $PSScriptRoot "make-msi.bat"), [Convert]::FromBase64String($makeMsiB64))
} catch {
    Write-Host "ERROR: failed to write make-msi.bat -- $_" -ForegroundColor Red
    Read-Host "Press Enter to close"
    exit 1
}

if (-not (Test-Path "app\__init__.py")) {
    Write-Host "ERROR: app\__init__.py was not created." -ForegroundColor Red
    Read-Host "Press Enter to close"
    exit 1
}
if (-not (Test-Path "make-msi.bat")) {
    Write-Host "ERROR: make-msi.bat was not created." -ForegroundColor Red
    Read-Host "Press Enter to close"
    exit 1
}
Write-Host "Both files written and confirmed."

Write-Host ""
Write-Host "============================================================"
Write-Host "  Source updated. Rebuilding exe + msi..."
Write-Host "============================================================"
cmd /c "make-msi.bat"

Write-Host ""
Write-Host "============================================================"
Write-Host "  Done."
Write-Host "============================================================"
Read-Host "Press Enter to close"
